import { ScrollView, Text, View } from 'react-native';

function Row({ title }) {
  return (
    <View style={{ paddingVertical: 8 }}>
      <Text>{title}</Text>
    </View>
  );
}

export default function ListScreen() {
  const items = [
    { id: '1', name: 'Alpha' },
    { id: '2', name: 'Beta' },
    { id: '3', name: 'Gamma' },
  ];

  // Uses stable unique key (item.id) instead of array index
  return (
    <ScrollView>
      {items.map((item) => (
        <Row key={item.id} title={item.name} />
      ))}
    </ScrollView>
  );
}","path":"/root/.openclaw/workspace/output/fixed/ListScreen.fixed.txt"},"function":"write"}

