@Component
export struct RNHostPage {
  @State title: string = 'RNOH Host Page';
  @StorageLink('RNAbility') rnAbility: RNAbility | undefined = undefined;

  aboutToAppear() {
    console.info('RNHostPage aboutToAppear');
  }

