[ACTION] {"args":{"edits":[{"newText":"def read_dockerfile(path: str) -> list[str]:
    """Read Dockerfile, returning non-comment lines, with multi-line commands merged."""
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Filter out comment lines and handle line continuations
    merged_lines = []
    current_line = ""

    for line in lines:
        stripped = line.strip()

        # Skip comment lines entirely
        if stripped.startswith('#'):
            continue

        if not stripped:
            continue

        # Check if this line ends with a continuation (backslash)
        if current_line:
            # Continue previous line
            if stripped.endswith('\\'):
                current_line += " " + stripped[:-1]
            else:
                current_line += " " + stripped
                merged_lines.append(current_line)
                current_line = ""
        else:
            # New instruction
            if stripped.endswith('\\'):
                current_line = stripped[:-1]
            else:
                merged_lines.append(stripped)
                current_line = ""

    # Handle any remaining line (shouldn't happen but just in case)
    if current_line:
        merged_lines.append(current_line)

    return merged_lines","oldText":"def read_dockerfile(path: str) -> list[str]:
    """Read Dockerfile, returning non-comment lines."""
    with open(path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Filter out comment lines (lines that start with # after stripping)
    non_comment_lines = []
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith('#'):
