[ACTION] {"args":{"content":"import React, { useEffect, useState, useCallback, useMemo } from 'react';
import { View, Text, Button, TouchableOpacity, StyleSheet } from 'react-native';

// Child component wrapped with React.memo to prevent unnecessary re-renders
const Child = React.memo(function Child({ text, onPress, style }) {
  console.log('Child render'); // for demonstration
  return (
    <TouchableOpacity onPress={onPress}>
      <Text style={style}>{text}</Text>
    </TouchableOpacity>
  );
});

function getMeeting() {
  return new Promise(resolve =>
    setTimeout(() => resolve({ id: 'm1', title: 'Weekly Sync' }), 150)
  );
}

function getUserList() {
  return new Promise(resolve =>
    setTimeout(() => resolve([{ id: 'u1' }, { id: 'u2' }, { id: 'u3' }]), 180)
  );
}

export default function App() {
  const [count, setCount] = useState(0);
  const [state, setState] = useState({ loading: false, meeting: null, users: [] });

  useEffect(() => {
    // Merge async setState calls via Promise.all to trigger single render
    Promise.all([getMeeting(), getUserList()]).then(([meeting, users]) => {
      setState(prev => ({
        ...prev,
        loading: false,
        meeting,
        users
      }));
    });

    // Initial loading state set once before Promise.all
    setState(prev => ({ ...prev, loading: true }));
  }, []);

  // Guard against unchanged value to avoid extra render
  const increment = useCallback(() => {
    setCount(prev => {
      const next = prev < 5 ? prev + 1 : prev;
      return next; // Only updates if value actually changes
    });
  }, []);

  // Stable callback for Child component
  const handleChildPress = useCallback(() => {
    console.log('child tapped');
  }, []);

  // Stable style object via useMemo (or StyleSheet)
  const childStyle = useMemo(() => [styles.childText], []);

  return (
    <View style={styles.container}>
      <Text>Count: {count}</Text>
      <Child
        text="Tap me"
        onPress={handleChildPress}
        style={childStyle}
      />
      <Button title="Increase" onPress={increment} />
      <Text>
        {state.loading ? 'Loading...' : `Meeting: ${state.meeting?.title || '-'} / Users: ${state.users.length}`}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    padding: 16
  },
  childText: {
    marginTop: 12,
    color: 'blue'
  }
});","path":"/root/.openclaw/workspace/output/fixed/App.fixed.txt"},"function":"write"}

