import re
import json

def analyze_craft(text, version):
    diagnostics = []

    # 1. Passive voice patterns
    passive_patterns = [
        r'\b(was|were|been|being|is|are|am)\s+((\w+ed|taken|given|shown|known|seen|heard|felt|made|done|written|broken|spoken)\b)',
        r'\b(was|were|been|being)\s+\w+ed\b',
    ]
    for i, line in enumerate(text.split('\n'), 1):
        for pattern in passive_patterns:
            matches = re.finditer(pattern, line, re.IGNORECASE)
            for m in matches:
                diagnostics.append({
                    "rule": "passive_voice",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": m.group(),
                    "severity": "medium"
                })

    # 2. Weak verbs
    weak_verbs = ['was', 'were', 'is', 'are', 'am', 'had', 'has', 'have', 'been', 'being', 'got', 'get', 'got']
    for i, line in enumerate(text.split('\n'), 1):
        words = line.split()
        for j, word in enumerate(words):
            if word.lower() in weak_verbs:
                # Check if it's part of a passive construction (already caught) or simple state
                if len(words) > j + 1 and words[j+1].endswith('ed'):
                    continue  # likely passive
                diagnostics.append({
                    "rule": "weak_verb",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": word,
                    "severity": "low"
                })

    # 3. Adverb overuse
    adverb_pattern = r'\b(\w+ly)\b'
    for i, line in enumerate(text.split('\n'), 1):
        matches = re.findall(adverb_pattern, line)
        if len(matches) > 1:
            diagnostics.append({
                "rule": "adverb_overuse",
                "line": i,
                "text": line.strip()[:100],
                "matches": matches,
                "count": len(matches),
                "severity": "medium"
            })
        for m in re.finditer(adverb_pattern, line):
            diagnostics.append({
                "rule": "adverb",
                "line": i,
                "text": line.strip()[:100],
                "match": m.group(),
                "severity": "low"
            })

    # 4. Clichés
    clichés = [
        r'dark and stormy',
        r'ghost story',
        r'needle in a haystack',
        r'heart was racing',
        r'cold sweat',
        r'deer in headlights',
        r'keep (playing|going) (on|and on)',
        r'as if it would never end',
        r'scene from',
        r'on the tip of your tongue',
    ]
    for i, line in enumerate(text.split('\n'), 1):
        for cliché in clichés:
            matches = re.finditer(cliché, line, re.IGNORECASE)
            for m in matches:
                diagnostics.append({
                    "rule": "cliché",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": m.group(),
                    "severity": "high"
                })

    # 5. Repetition
    words = re.findall(r'\b\w+\b', text.lower())
    word_freq = {}
    for w in words:
        if len(w) > 3:
            word_freq[w] = word_freq.get(w, 0) + 1

    repetitive = {w: c for w, c in word_freq.items() if c > 4}

    # Check for immediate word repetition in lines
    for i, line in enumerate(text.split('\n'), 1):
        words_in_line = line.split()
        for j in range(len(words_in_line) - 1):
            if words_in_line[j].lower() == words_in_line[j+1].lower() and len(words_in_line[j]) > 2:
                diagnostics.append({
                    "rule": "repetition",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": words_in_line[j],
                    "severity": "medium"
                })

    for word, count in repetitive.items():
        # Find lines with this word
        for i, line in enumerate(text.split('\n'), 1):
            if re.search(r'\b' + word + r'\b', line, re.IGNORECASE):
                diagnostics.append({
                    "rule": "repetition",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": word,
                    "count": count,
                    "severity": "low"
                })

    # 6. Show don't tell indicators
    tell_phrases = [
        r'she felt (scared|nervous|afraid|angry|sad|guilty)',
        r'she was (scared|nervous|afraid|angry|sad|guilty)',
        r'it was (very|really) (scary|strange|creepy)',
        r'she (thought|knew|believed) (that )?',
        r'he/she was (the \w+est)',
    ]
    for i, line in enumerate(text.split('\n'), 1):
        for phrase in tell_phrases:
            matches = re.finditer(phrase, line, re.IGNORECASE)
            for m in matches:
                diagnostics.append({
                    "rule": "show_dont_tell",
                    "line": i,
                    "text": line.strip()[:100],
                    "match": m.group(),
                    "severity": "high"
                })

    return diagnostics

# Read drafts
with open('input/draft_v1.md', 'r') as f:
    v1 = f.read()
with open('input/draft_v2.md', 'r') as f:
    v2 = f.read()

# Analyze
analysis_v1 = analyze_craft(v1, 1)
analysis_v2 = analyze_craft(v2, 2)

# Save raw diagnostics
with open('output/analysis_v1.json', 'w') as f:
    json.dump(analysis_v1, f, indent=2)
with open('output/analysis_v2.json', 'w') as f:
    json.dump(analysis_v2, f, indent=2)

print(f"V1 issues: {len(analysis_v1)}")
print(f"V2 issues: {len(analysis_v2)}")

# Count by category
def count_by_category(diagnostics):
    counts = {}
    for d in diagnostics:
        rule = d['rule']
        # Consolidate similar rules
        if rule in ['adverb', 'adverb_overuse']:
            rule = 'adverbs'
        if rule == 'weak_verb':
            rule = 'weak_verbs'
        counts[rule] = counts.get(rule, 0) + 1
    return counts

v1_counts = count_by_category(analysis_v1)
v2_counts = count_by_category(analysis_v2)

print("\nV1 counts:", v1_counts)
print("V2 counts:", v2_counts)

# Calculate deltas
deltas = {}
for k in set(v1_counts.keys()) | set(v2_counts.keys()):
    delta = v2_counts.get(k, 0) - v1_counts.get(k, 0)
    deltas[k] = delta

print("\nDeltas:", deltas)

# Determine overall trend
total_v1 = sum(v1_counts.values())
total_v2 = sum(v2_counts.values())
if total_v2 < total_v1:
    overall = "improved"
elif total_v2 > total_v1:
    overall = "regressed"
else:
    overall = "no_change"

comparison = {
    "overall_trend": overall,
    "total_issues_v1": total_v1,
    "total_issues_v2": total_v2,
    "category_deltas": deltas
}

with open('output/compare.json', 'w') as f:
    json.dump(comparison, f, indent=2)

print(f"\nOverall: {overall}")
EOF","workdir":"/root/.openclaw/workspace"},"function":"exec"}

