import os
import sys
import unittest

# Ensure src is importable
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

from rubric import compute_score, classify_score, load_weights, load_thresholds

WORKSPACE = os.path.join(os.path.dirname(__file__), "..")


class TestComputeScore(unittest.TestCase):
    """Tests for compute_score using the project's rubric and submission files."""

    @classmethod
    def setUpClass(cls):
        cls.weights = load_weights(os.path.join(WORKSPACE, "rubrics", "rubric.json"))
        # Load submissions
        cls.submissions = {}
        with open(os.path.join(WORKSPACE, "data", "submissions.jsonl"), "r") as f:
            for line in f:
                rec = json.loads(line.strip())
                cls.submissions[rec["student_id"]] = rec["scores"]

    def test_s1_score(self):
        """S1: collab=3, crit=2, comm=4 with weights 0.3/0.4/0.3 → 2.90"""
        score = compute_score(self.submissions["S1"], self.weights)
        self.assertEqual(score, 2.90)

    def test_s2_missing_criterion(self):
        """S2: collab=1, crit=2, missing comm → comm treated as 0 → 1.10"""
        score = compute_score(self.submissions["S2"], self.weights)
        self.assertEqual(score, 1.10)

    def test_percentage_weights_normalized(self):
        """Percentage-style weights (30/40/30) should still yield 2.90 for S1."""
        pct_weights = {"collaboration": 30, "critical_thinking": 40, "communication": 30}
        score = compute_score(self.submissions["S1"], pct_weights)
        self.assertEqual(score, 2.90)


class TestClassifyScore(unittest.TestCase):
    """Tests for classify_score using thresholds from config.json."""

    @classmethod
    def setUpClass(cls):
        cls.thresholds = load_thresholds(os.path.join(WORKSPACE, "config.json"))

    def test_proficient(self):
        """2.90 falls in the proficient band (emerging_max < 2.90 ≤ proficient_max)."""
        self.assertEqual(classify_score(2.90, self.thresholds), "proficient")

    def test_emerging(self):
        """1.10 falls in the emerging band (≤ emerging_max=1.99)."""
        self.assertEqual(classify_score(1.10, self.thresholds), "emerging")


if __name__ == "__main__":
    unittest.main()
","path":"tests/test_rubric.py"},"function":"write"}

