        if not self._skip:
            self._pieces.append(data)

    def get_text(self) -> str:
        return "".join(self._pieces).strip()


def strip_tags(html: str) -> str:
    p = _TextExtractor()
    p.feed(html)
    return p.get_text()


class _InfoboxParser(HTMLParser):
